package android.view;public class ViewGroup extends View {public ViewGroup(){}public ViewGroup(android.content.Context c){super(c);}public java.util.List<View> children=new java.util.ArrayList<>();public void addView(View v){children.add(v);v.parent=this;}public void addView(View v,LayoutParams p){addView(v);v.setLayoutParams(p);}public static class LayoutParams {public static final int MATCH_PARENT=-1,WRAP_CONTENT=-2;public int width,height;public LayoutParams(int w,int h){width=w;height=h;}}}
